catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        g_form.clearOptions('email_type');

    }

    if (newValue == 'c0ccc3d21b079950ff37eb14b24bcb9f') {
		// Adding options to this field
        g_form.addOption('email_type', 'Generic', 'Generic');
        g_form.addOption('email_type', 'Trade Mismatch','Trade Mismatch');
        g_form.addOption('email_type', 'Trade Confirmed', 'Trade Confirmed');
        g_form.addOption('email_type', 'Allocation Trade Mismatch', 'Allocation Trade Mismatch');

		// Removing options for this field
		g_form.removeOption('email_type', 'Unmatched Trade Economics');
        g_form.removeOption('email_type', 'Unmatched SSIs');
        g_form.removeOption('email_type', 'Other Unmatched Error');
        g_form.removeOption('email_type', "Counterparty Doesn't Recognize Trade");
        g_form.removeOption('email_type', "Counterparty Hasn't released Instructions");
        g_form.removeOption('email_type', 'Cash Mismatch Identified');
        g_form.removeOption('email_type', 'HSBC May Not Be Able To Deliver');
        g_form.removeOption('email_type', 'Counterparty May Not Be Able To Deliver');
        g_form.removeOption('email_type', 'Other Matched Error');
    }

    if (newValue == '0d79d6da1b30e110ff37eb14b24bcb71') {
        // Removing options to this field
		g_form.removeOption('email_type', 'Trade Mismatch');
        g_form.removeOption('email_type', 'Trade Confirmed');
        g_form.removeOption('email_type', 'Allocation Trade Mismatch');

		// Adding options to this field
		g_form.addOption('email_type', 'Generic', 'Generic');
		g_form.addOption('email_type', 'Unmatched Trade Economics', 'Unmatched Trade Economics');
        g_form.addOption('email_type', 'Unmatched SSIs', 'Unmatched SSIs');
        g_form.addOption('email_type', 'Other Unmatched Error', 'Other Unmatched Error');
        g_form.addOption('email_type', "Counterparty Doesn't Recognize Trade", "Counterparty Doesn't Recognize Trade");
        g_form.addOption('email_type', "Counterparty Hasn't released Instructions", "Counterparty Hasn't released Instructions");
        g_form.addOption('email_type', 'Cash Mismatch Identified', 'Cash Mismatch Identified');
        g_form.addOption('email_type', 'HSBC May Not Be Able To Deliver', 'HSBC May Not Be Able To Deliver');
        g_form.addOption('email_type', 'Counterparty May Not Be Able To Deliver', 'Counterparty May Not Be Able To Deliver');
        g_form.addOption('email_type', 'Other Matched Error', 'Other Matched Error');
    }


}
